#!/usr/bin/env node

import { createHash } from "node:crypto";
import { existsSync, realpathSync } from "node:fs";
import { mkdir, readFile, readdir, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import YAML from "yaml";

export const GENERATED_MARKER =
  "# Generated by scripts/generate-openai-metadata.mjs; DO NOT EDIT.";

const CURATED_SHORT_DESCRIPTIONS = Object.freeze({
  "aeo-audit": "Audit answer clarity and supported structured search features",
  "conversion-optimization":
    "Diagnose conversion friction and prioritize evidence-led tests",
  "geo-audit": "Audit source-worthy clarity for generative search systems",
  "landing-copywriter": "Write evidence-backed landing-page copy that converts",
  "landing-design-system": "Build accessible landing-page tokens and components",
  "landing-page-build": "Orchestrate the full evidence-first landing workflow",
  "landing-page-design": "Design distinctive, accessible landing-page sections",
  "landing-page-implementation":
    "Implement approved sections with production discipline",
  "landing-page-qa": "Verify landing pages in-browser across critical states",
  "landing-research":
    "Research buyers, competitors, evidence, and page strategy",
  "marketing-campaign":
    "Plan channel-aware campaigns with measurable conversion",
  "motion-video": "Design product motion that proves one sourced claim",
  "seo-audit": "Audit technical SEO, discoverability, and search eligibility",
  "creative-direction":
    "Shape three distinctive, evidence-led visual territories",
  "media-sourcing":
    "Source landing-page media with defensible rights evidence",
  "technology-curator":
    "Approve web dependencies with current measured evidence",
  "webgl-3d": "Prove selective 3D with strict fallback and GPU budgets",
  "landing-red-team":
    "Block weak landing-page work with exact browser evidence",
});

const CURATED_DISPLAY_NAMES = Object.freeze({
  "webgl-3d": "WebGL and 3D",
});

const CURATED_DEFAULT_PROMPTS = Object.freeze({
  "creative-direction":
    "Use $creative-direction to research and compare three original creative territories for the active landing-page section.",
  "media-sourcing":
    "Use $media-sourcing to choose and clear media for the selected active landing-page section before implementation.",
  "technology-curator":
    "Use $technology-curator to evaluate the smallest safe technology choice for the active landing-page section.",
  "webgl-3d":
    "Use $webgl-3d to decide and prove the smallest accessible 3D lane for the active landing-page section.",
  "landing-red-team":
    "Use $landing-red-team to independently attack and score the implemented active section with P0-P3 evidence.",
});

const DISPLAY_TERMS = Object.freeze({
  aeo: "AEO",
  geo: "GEO",
  qa: "QA",
  seo: "SEO",
  webgl: "WebGL",
  "3d": "3D",
});

function normalizeSpace(value) {
  return value.replace(/\s+/g, " ").trim();
}

function stripTerminalPunctuation(value) {
  return value.replace(/[.!?:;,]+$/u, "").trim();
}

function truncateAtWord(value, maximum) {
  if (value.length <= maximum) return value;
  const prefix = value.slice(0, maximum - 3).replace(/\s+\S*$/u, "").trim();
  return `${prefix || value.slice(0, maximum - 3).trim()}...`;
}

function fallbackShortDescription(name, description) {
  const firstSentence = normalizeSpace(description).split(/(?<=[.!?])\s/u, 1)[0];
  let candidate = stripTerminalPunctuation(firstSentence);
  candidate = truncateAtWord(candidate, 64);

  if (candidate.length < 25) {
    candidate = truncateAtWord(
      `${candidate || `Run ${displayName(name)}`} with evidence controls`,
      64,
    );
  }

  return candidate;
}

function promptAction(shortDescription, description) {
  const source = shortDescription.endsWith("...")
    ? normalizeSpace(description).split(/(?<=[.!?])\s/u, 1)[0]
    : shortDescription;
  const action = stripTerminalPunctuation(source);
  return action.charAt(0).toLowerCase() + action.slice(1);
}

export function displayName(name) {
  if (CURATED_DISPLAY_NAMES[name]) return CURATED_DISPLAY_NAMES[name];
  return name
    .split("-")
    .map((term) => DISPLAY_TERMS[term] ?? `${term.charAt(0).toUpperCase()}${term.slice(1)}`)
    .join(" ");
}

export function buildOpenAiMetadata({ name, description }) {
  if (typeof name !== "string" || typeof description !== "string") {
    throw new TypeError("OpenAI metadata requires string name and description fields");
  }

  const shortDescription =
    CURATED_SHORT_DESCRIPTIONS[name] ?? fallbackShortDescription(name, description);
  if (shortDescription.length < 25 || shortDescription.length > 64) {
    throw new RangeError(
      `short_description for ${name} must contain 25 through 64 characters`,
    );
  }

  return {
    interface: {
      display_name: displayName(name),
      short_description: shortDescription,
      default_prompt:
        CURATED_DEFAULT_PROMPTS[name] ??
        `Use $${name} to ${promptAction(shortDescription, description)}.`,
    },
  };
}

export function skillContractHash({ name, description }) {
  return createHash("sha256")
    .update(JSON.stringify({ name, description }))
    .digest("hex");
}

export function serializeOpenAiMetadata(contract) {
  const metadata = buildOpenAiMetadata(contract);
  const { display_name, short_description, default_prompt } = metadata.interface;
  return `${GENERATED_MARKER}
# source_sha256: ${skillContractHash(contract)}
interface:
  display_name: ${JSON.stringify(display_name)}
  short_description: ${JSON.stringify(short_description)}
  default_prompt: ${JSON.stringify(default_prompt)}
`;
}

export function parseSkillFrontmatter(source, sourceName = "SKILL.md") {
  const match = source.match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/u);
  if (!match) {
    throw new Error(`${sourceName} must begin with YAML frontmatter`);
  }

  const document = YAML.parseDocument(match[1], {
    prettyErrors: true,
    uniqueKeys: true,
  });
  if (document.errors.length > 0) {
    throw new Error(
      `${sourceName} frontmatter YAML is invalid: ${document.errors
        .map((error) => error.message)
        .join("; ")}`,
    );
  }

  const value = document.toJS();
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${sourceName} frontmatter must be a YAML mapping`);
  }
  return { frontmatter: value, body: source.slice(match[0].length) };
}

export async function readSkillContract(skillDirectory) {
  const skillPath = join(skillDirectory, "SKILL.md");
  const source = await readFile(skillPath, "utf8");
  return parseSkillFrontmatter(source, skillPath).frontmatter;
}

export async function generateMetadataForSkill(skillDirectory, { check = false } = {}) {
  const contract = await readSkillContract(skillDirectory);
  const expected = serializeOpenAiMetadata(contract);
  const outputPath = join(skillDirectory, "agents", "openai.yaml");

  if (check) {
    if (!existsSync(outputPath)) {
      return { ok: false, outputPath, reason: "missing" };
    }
    const actual = await readFile(outputPath, "utf8");
    return {
      ok: actual === expected,
      outputPath,
      reason: actual === expected ? null : "stale",
    };
  }

  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, expected, "utf8");
  return { ok: true, outputPath, reason: null };
}

async function skillNames(root) {
  const entries = await readdir(join(root, "skills"), { withFileTypes: true });
  return entries
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .sort();
}

function parseArguments(argv) {
  const options = { root: process.cwd(), check: false, skills: [] };
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === "--check") {
      options.check = true;
    } else if (argument === "--root") {
      options.root = resolve(argv[++index]);
    } else if (argument === "--skill") {
      options.skills.push(argv[++index]);
    } else {
      throw new Error(`Unknown argument: ${argument}`);
    }
  }
  return options;
}

async function main() {
  const options = parseArguments(process.argv.slice(2));
  const names = options.skills.length > 0 ? options.skills : await skillNames(options.root);
  let failed = false;

  for (const name of names) {
    const result = await generateMetadataForSkill(join(options.root, "skills", name), {
      check: options.check,
    });
    const status = result.ok ? (options.check ? "fresh" : "generated") : result.reason;
    process.stdout.write(`${status}: ${result.outputPath}\n`);
    failed ||= !result.ok;
  }

  if (failed) process.exitCode = 1;
}

const invokedPath = process.argv[1] ? realpathSync(resolve(process.argv[1])) : null;
if (invokedPath === realpathSync(fileURLToPath(import.meta.url))) {
  main().catch((error) => {
    process.stderr.write(`${error.stack ?? error.message}\n`);
    process.exitCode = 1;
  });
}
